pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a minimal ERC20-like token that transferFrom reverts if from has insufficient balance
        // We need to set up a token address that c can call.
        // The token will be deployed in setUp? No, deploying another contract inside test is allowed.
        // Create a token that always reverts on transferFrom (simulating failure case)
        // Then call c.transfer; for reference, it will revert; for mutant, it returns true.
        // But the test must assert something on c's public surface. The return value of transfer is captured via try/catch.
        // We can check that c.transfer reverts for reference and succeeds for mutant. But the assertion must differ.
        // We'll deploy a token that reverts on any transferFrom.
        // Then call c.transfer with that token. In the reference, it reverts (the inner call reverts). In mutant, it returns true.
        // So in the test, we can try/catch and check the boolean.
        // However, the test must pass on reference and fail on mutant. We need to write the assertion that the reference satisfies and mutant breaks.
        // For reference, the transfer call reverts -> the try/catch returns false.
        // For mutant, it returns true -> the try/catch returns true.
        // So we can assert that the call reverts. On reference, it reverts (assertTrue(!ok) passes). On mutant, it doesn't revert (assertTrue(!ok) fails).
        // That gives the desired divergence.

        // Deploy a token that always reverts
        RevertingToken token = new RevertingToken();
        address tokenAddr = address(token);
        address from = address(0xdead);
        address[] memory tos = new address[](1);
        tos[0] = address(0xbeef);
        uint v = 100;

        // Call transfer
        bool ok;
        try c.transfer(from, tokenAddr, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference will revert because the external call reverts, so ok = false.
        // The mutant returns true without call, so ok = true.
        assertTrue(!ok, "Reference reverts, mutant does not");
    }
}

contract RevertingToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}

